/**
  **************************************************************************
  * @file     esc.c
  * @brief    sensorless six step bldc control loop
  *
  * This is a compact port of the AM32 control scheme:
  *   - open loop ramp start with rotor alignment
  *   - bemf zero crossing detection, commutation 30 degrees after the
  *     crossing (waitTime = commutation_interval / 2)
  *   - desync detection by a bemf timeout, restart with a coast phase
  *   - slow duty ramp and speed governor
  *
  * The 20 kHz tick is generated by the adc preempt interrupt which is
  * synchronised with the pwm period (see esc_hw.c).
  **************************************************************************
  */

#include "at32f421_wk_config.h"
#include "esc.h"
#include "esc_config.h"

/* ------------------------------------------------------------------------- */
/* derived values                                                            */
/* ------------------------------------------------------------------------- */
#define ESC_TICK_US                   (50u)
#define US_TO_TICKS(us)               (((uint32_t)(us) + (ESC_TICK_US - 1u)) / ESC_TICK_US)
#define PM_TO_TICKS(pm)               (((uint32_t)(pm) * ESC_PWM_PERIOD_TICKS) / 1000u)

#define ALIGN_DUTY_TICKS              ((uint16_t)PM_TO_TICKS(ESC_ALIGN_DUTY_PERMILLE))
#define START_DUTY_TICKS              ((uint16_t)PM_TO_TICKS(ESC_START_DUTY_PERMILLE))
#define MIN_RUN_DUTY_TICKS            ((uint16_t)PM_TO_TICKS(ESC_MIN_RUN_DUTY_PERMILLE))
#define MAX_DUTY_TICKS                ((uint16_t)PM_TO_TICKS(ESC_MAX_DUTY_PERMILLE))
#if (ESC_MAX_ELEC_FREQ_HZ > 0u)
#define MIN_INTERVAL_TICKS            US_TO_TICKS(1000000u / (6u * ESC_MAX_ELEC_FREQ_HZ))
#else
#define MIN_INTERVAL_TICKS            (1u)   /* governor disabled */
#endif

/* ------------------------------------------------------------------------- */
/* state                                                                     */
/* ------------------------------------------------------------------------- */
static volatile uint8_t  s_state;
static volatile uint16_t s_duty_ticks;

static uint32_t s_tick;              /* 50 us ticks, only in the fast context  */
static uint32_t s_sub_tick;
static volatile uint32_t s_ms;       /* milliseconds                           */
static uint32_t s_state_ms;          /* ms when the state was entered          */

static uint8_t  s_step;              /* 1..6                                   */
static uint32_t s_step_tick;
static uint32_t s_interval_ticks;    /* filtered 60 degree time                */
static uint32_t s_blank_ticks;
static uint32_t s_zc_tick;
static uint8_t  s_zc_pre_seen;
static uint8_t  s_zc_found;
static uint8_t  s_zc_confirm;
static uint8_t  s_zc_lock;
static uint8_t  s_zc_pol_flip;       /* learned bemf polarity, 1 = inverted */
static uint8_t  s_zc_pol_valid;
static uint8_t  s_zc_pol_checked;
static int8_t   s_zc_pol_score;
static uint8_t  s_zc_pol_steps;
static uint32_t s_ol_interval_ticks;
static uint8_t  s_desync_count;
static uint32_t s_run_ms;

static uint8_t  s_armed;
static uint32_t s_arm_ms;
static uint32_t s_last_ms;
static uint32_t s_fault_ms;
static uint8_t  s_throttle_valid;
static int32_t  s_throttle_filt;
static uint16_t s_throttle_adc;
static uint16_t s_throttle_pm;
static uint16_t s_slow_div;
static esc_status_t s_status;

/* ------------------------------------------------------------------------- */
/* helpers                                                                   */
/* ------------------------------------------------------------------------- */
static uint32_t esc_blank_ticks_for(uint32_t interval_ticks)
{
  uint32_t blank = interval_ticks / ESC_BLANK_INTERVAL_DIV;

  if(blank < US_TO_TICKS(ESC_BLANK_MIN_US))
  {
    blank = US_TO_TICKS(ESC_BLANK_MIN_US);
  }
  if(blank > (interval_ticks / 4u))
  {
    blank = interval_ticks / 4u;
  }
  if(blank < 1u)
  {
    blank = 1u;
  }
  return blank;
}

static uint8_t esc_step_rising(uint8_t step)
{
  /* AM32 step table: odd steps have a rising bemf on the floating phase.
     the real slope depends on the motor wiring, it is learned during the
     open loop ramp (see esc_learn_polarity) */
  uint8_t rising = (step & 1u) ? 1u : 0u;

#if ESC_REVERSE_DIRECTION
  rising ^= 1u;
#endif
  rising ^= s_zc_pol_flip;
  return rising;
}

/* ------------------------------------------------------------------------- */
/* bemf zero crossing                                                        */
/* ------------------------------------------------------------------------- */
static uint8_t esc_zc_detect(uint16_t vfloat, uint16_t vneutral)
{
  int16_t diff;
  int16_t d;

  if(s_zc_found)
  {
    return 0;
  }
  if((s_tick - s_step_tick) < s_blank_ticks)
  {
    return 0;
  }

  diff = (int16_t)vfloat - (int16_t)vneutral;

  /* normalise the slope: for both a rising and a falling bemf the signal d
     goes from negative (before the crossing) to positive (after it) */
  d = esc_step_rising(s_step) ? diff : (int16_t)(-diff);

  if(!s_zc_pre_seen)
  {
    /* wait until the floating phase is clearly on the "before crossing" side */
    if(d < -(int16_t)ESC_ZC_THRESHOLD_COUNTS)
    {
      s_zc_pre_seen = 1;
      s_zc_confirm = 0;
    }
    return 0;
  }

  if(d > (int16_t)(ESC_ZC_THRESHOLD_COUNTS / 2u))
  {
    s_zc_confirm++;
    if(s_zc_confirm >= ESC_ZC_CONFIRM_SAMPLES)
    {
      s_zc_found = 1;
      s_zc_tick = s_tick - (uint32_t)(ESC_ZC_CONFIRM_SAMPLES - 1u);
      return 1;
    }
  }
  else
  {
    s_zc_confirm = 0;
  }

  return 0;
}

/* ------------------------------------------------------------------------- */
/* commutation                                                               */
/* ------------------------------------------------------------------------- */
static void esc_commutate(void)
{
  uint32_t step_ticks = s_tick - s_step_tick;

  if(s_state == ESC_STATE_RUN)
  {
    uint32_t filtered = (s_interval_ticks * 3u + step_ticks) / 4u;

    if(filtered < 2u)
    {
      filtered = 2u;
    }
    if(filtered > US_TO_TICKS(ESC_OL_START_INTERVAL_US))
    {
      filtered = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
    }
    s_interval_ticks = filtered;
  }

#if ESC_REVERSE_DIRECTION
  if(s_step <= 1u)
  {
    s_step = 6u;
  }
  else
  {
    s_step--;
  }
#else
  if(s_step >= 6u)
  {
    s_step = 1u;
  }
  else
  {
    s_step++;
  }
#endif

  esc_hw_apply_step(s_step, s_duty_ticks);

  s_step_tick = s_tick;
  s_zc_found = 0;
  s_zc_pre_seen = 0;
  s_zc_confirm = 0;
  s_zc_pol_checked = 0;
  s_blank_ticks = esc_blank_ticks_for(s_interval_ticks);
}

static void esc_desync(void)
{
  esc_hw_all_off();

  /* if the open loop never produced a usable bemf, try the inverted slope
     on the next attempt (the motor wiring decides the bemf polarity) */
  if(s_state == ESC_STATE_OPENLOOP)
  {
    s_zc_pol_flip ^= 1u;
    s_zc_pol_valid = 0;
    s_zc_lock = 0;
  }

  s_duty_ticks = 0;
  s_zc_found = 0;
  s_zc_lock = 0;
  s_interval_ticks = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
  s_state_ms = s_ms;
  s_desync_count++;

  if(s_desync_count >= ESC_MAX_DESYNCS)
  {
    s_state = ESC_STATE_FAULT;
  }
  else
  {
    s_state = ESC_STATE_COAST;
  }
}

static void esc_enter_align(void)
{
  s_state = ESC_STATE_ALIGN;
  s_state_ms = s_ms;

  s_step = 1;
  s_step_tick = s_tick;
  s_interval_ticks = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
  s_blank_ticks = esc_blank_ticks_for(s_interval_ticks);

  s_zc_found = 0;
  s_zc_pre_seen = 0;
  s_zc_confirm = 0;
  s_zc_lock = 0;
  s_zc_pol_checked = 0;
  s_zc_pol_score = 0;
  s_zc_pol_steps = 0;

  if(s_duty_ticks < ALIGN_DUTY_TICKS)
  {
    s_duty_ticks = ALIGN_DUTY_TICKS;
  }

  esc_hw_apply_step(s_step, s_duty_ticks);
  esc_hw_update_duty(s_duty_ticks);
}

static void esc_enter_openloop(void)
{
  s_state = ESC_STATE_OPENLOOP;
  s_state_ms = s_ms;

  s_ol_interval_ticks = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
  s_interval_ticks = s_ol_interval_ticks;
  s_step_tick = s_tick;
  s_blank_ticks = esc_blank_ticks_for(s_interval_ticks);

  s_zc_found = 0;
  s_zc_pre_seen = 0;
  s_zc_confirm = 0;
  s_zc_lock = 0;
  s_zc_pol_checked = 0;
  s_zc_pol_score = 0;
  s_zc_pol_steps = 0;
}

static void esc_stop(void)
{
  esc_hw_all_off();

  s_state = ESC_STATE_IDLE;
  s_duty_ticks = 0;
  s_zc_found = 0;
  s_zc_lock = 0;
  s_interval_ticks = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
}

/* ------------------------------------------------------------------------- */
/* fast tick, called from the adc interrupt every 50 us                      */
/* ------------------------------------------------------------------------- */
/* During the forced ramp the rotor is nearly synchronised with the applied
   step, so the sign of the floating phase bemf just after the blanking time
   tells whether the slope convention is inverted (it depends on the motor
   wiring).  Vote over 6 steps and flip the convention if it is consistent. */
static void esc_learn_polarity(uint16_t vfloat, uint16_t vneutral)
{
  int16_t diff;
  int16_t d;

  if(s_zc_pol_valid || (s_zc_pol_checked != 0u))
  {
    return;
  }
  if((s_tick - s_step_tick) < s_blank_ticks)
  {
    return;
  }

  diff = (int16_t)vfloat - (int16_t)vneutral;
  d = esc_step_rising(s_step) ? diff : (int16_t)(-diff);

  s_zc_pol_checked = 1;
  if(d < -(int16_t)ESC_ZC_THRESHOLD_COUNTS)
  {
    s_zc_pol_score++;
  }
  else if(d > (int16_t)ESC_ZC_THRESHOLD_COUNTS)
  {
    s_zc_pol_score--;
  }

  s_zc_pol_steps++;
  if(s_zc_pol_steps >= 6u)
  {
    if(s_zc_pol_score <= -5)
    {
      s_zc_pol_flip ^= 1u;
      s_zc_pol_valid = 1;
      s_zc_lock = 0;
    }
    else if(s_zc_pol_score >= 5)
    {
      s_zc_pol_valid = 1;
    }
    s_zc_pol_score = 0;
    s_zc_pol_steps = 0;
  }
}

static void esc_openloop_tick(uint16_t vfloat, uint16_t vneutral)
{
  uint8_t zc;

  esc_learn_polarity(vfloat, vneutral);

  /* like the AM32 polling start: the zero cross drives the commutation as
     soon as it is usable, the forced interval is only the fallback that
     keeps accelerating the rotor while there is no bemf yet */
  zc = esc_zc_detect(vfloat, vneutral);
  if(zc)
  {
    if(s_zc_lock < 0xFFu)
    {
      s_zc_lock++;
    }
  }

  if((s_ms - s_state_ms) >= ESC_OL_TIMEOUT_MS)
  {
    esc_desync();
    return;
  }

  if(zc && (s_zc_lock >= ESC_ZC_LOCK_STEPS))
  {
    /* bemf is usable, the crossing is 30 degrees into the 60 degree step */
    uint32_t zc_delta = s_zc_tick - s_step_tick;

    s_interval_ticks = zc_delta * 2u;
    if(s_interval_ticks < MIN_INTERVAL_TICKS)
    {
      s_interval_ticks = MIN_INTERVAL_TICKS;
    }
    if(s_interval_ticks > US_TO_TICKS(ESC_OL_START_INTERVAL_US))
    {
      s_interval_ticks = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
    }

    /* keep the zero cross found flag, esc_run_tick applies the remaining
       30 degrees before the first closed loop commutation */
    s_state = ESC_STATE_RUN;
    s_state_ms = s_ms;
    s_run_ms = s_ms;
    s_desync_count = 0;
    s_zc_lock = 0;
    return;
  }

  if(s_zc_found)
  {
    /* commute 30 degrees after the crossing, using the measured time */
    uint32_t wait = s_zc_tick - s_step_tick;

    if(wait < 1u)
    {
      wait = 1u;
    }
    if((s_tick - s_zc_tick) >= wait)
    {
      s_interval_ticks = wait * 2u;
      if(s_interval_ticks < MIN_INTERVAL_TICKS)
      {
        s_interval_ticks = MIN_INTERVAL_TICKS;
      }
      esc_commutate();
    }
    return;
  }

  /* no bemf in this step: forced commutation and accelerate the ramp */
  if((s_tick - s_step_tick) >= (s_ol_interval_ticks + (s_ol_interval_ticks / 2u)))
  {
    s_zc_lock = 0;
    s_interval_ticks = s_ol_interval_ticks;
    esc_commutate();

    s_ol_interval_ticks = (s_ol_interval_ticks * (100u - ESC_OL_ACCEL_PERCENT)) / 100u;
    if(s_ol_interval_ticks < US_TO_TICKS(ESC_OL_MIN_INTERVAL_US))
    {
      s_ol_interval_ticks = US_TO_TICKS(ESC_OL_MIN_INTERVAL_US);
    }
  }
}

static void esc_run_tick(uint16_t vfloat, uint16_t vneutral)
{
  uint32_t wait;
  uint32_t timeout;

  if((s_ms - s_run_ms) >= ESC_RUN_OK_MS)
  {
    s_desync_count = 0;
    s_run_ms = s_ms;
  }

  if(!s_zc_found)
  {
    esc_zc_detect(vfloat, vneutral);

    if(!s_zc_found)
    {
      timeout = (s_interval_ticks * ESC_DESYNC_TIMEOUT_NUM) / 2u + ESC_DESYNC_TIMEOUT_EXTRA;
      if((s_tick - s_step_tick) > timeout)
      {
        esc_desync();
      }
      return;
    }
  }

  /* 30 degrees after the zero crossing, like AM32's waitTime */
  wait = s_interval_ticks / 2u;
  if(wait < 1u)
  {
    wait = 1u;
  }

  if((s_tick - s_zc_tick) >= wait)
  {
    esc_commutate();
  }
}

void esc_fast_tick(uint16_t vfloat, uint16_t vneutral)
{
  s_tick++;
  s_sub_tick++;
  if(s_sub_tick >= 20u)
  {
    s_sub_tick = 0;
    s_ms++;
  }

  switch(s_state)
  {
    case ESC_STATE_ALIGN:
      if((s_ms - s_state_ms) >= ESC_ALIGN_MS)
      {
        esc_enter_openloop();
      }
      break;

    case ESC_STATE_OPENLOOP:
      esc_openloop_tick(vfloat, vneutral);
      break;

    case ESC_STATE_RUN:
      esc_run_tick(vfloat, vneutral);
      break;

    case ESC_STATE_COAST:
      if((s_ms - s_state_ms) >= ESC_RESTART_COAST_MS)
      {
        esc_enter_align();
      }
      break;

    default:
      break;
  }
}

/* ------------------------------------------------------------------------- */
/* slow task, 1 kHz                                                          */
/* ------------------------------------------------------------------------- */
static uint16_t esc_map_throttle(int32_t value)
{
  if(value <= (int32_t)ESC_THROTTLE_ADC_LOW)
  {
    return 0;
  }
  if(value >= (int32_t)ESC_THROTTLE_ADC_HIGH)
  {
    return 1000;
  }
  return (uint16_t)(((value - (int32_t)ESC_THROTTLE_ADC_LOW) * 1000) /
                    ((int32_t)ESC_THROTTLE_ADC_HIGH - (int32_t)ESC_THROTTLE_ADC_LOW));
}

static void esc_slow_update(uint32_t elapsed_ms)
{
  uint32_t primask;
  uint16_t raw;
  uint16_t target;
  uint16_t duty;
  uint32_t ramp;
  uint8_t want_run;

  raw = esc_hw_read_throttle();
  s_throttle_adc = raw;

  if(!s_throttle_valid)
  {
    s_throttle_filt = (int32_t)raw;
    s_throttle_valid = 1;
  }
  s_throttle_filt += ((int32_t)raw - s_throttle_filt) / ESC_THROTTLE_FILTER_DIV;

  s_throttle_pm = esc_map_throttle(s_throttle_filt);

  /* arming: the pot has to be at zero after power up */
  if(!s_armed)
  {
    if(s_throttle_pm <= ESC_ARM_MAX_PM)
    {
      s_arm_ms += elapsed_ms;
      if(s_arm_ms >= ESC_ARM_DELAY_MS)
      {
        s_armed = 1;
      }
    }
    else
    {
      s_arm_ms = 0;
    }
  }

  /* fault recovery: throttle to zero */
  if(s_state == ESC_STATE_FAULT)
  {
    if(s_throttle_pm == 0u)
    {
      s_fault_ms += elapsed_ms;
      if(s_fault_ms >= 500u)
      {
        primask = __get_PRIMASK();
        __disable_irq();
        esc_stop();
        s_desync_count = 0;
        s_fault_ms = 0;
        __set_PRIMASK(primask);
      }
    }
    else
    {
      s_fault_ms = 0;
    }
  }

  if(s_throttle_pm == 0u)
  {
    s_desync_count = 0;
  }

  want_run = (uint8_t)(s_armed && (s_state != ESC_STATE_FAULT) &&
                       (s_throttle_pm >= ESC_THROTTLE_START_PM));

  primask = __get_PRIMASK();
  __disable_irq();
  if(want_run)
  {
    if(s_state == ESC_STATE_IDLE)
    {
      esc_enter_align();
    }
  }
  else
  {
    if((s_state != ESC_STATE_IDLE) && (s_state != ESC_STATE_FAULT))
    {
      esc_stop();
    }
  }
  __set_PRIMASK(primask);

  /* duty target */
  target = 0;
  if((s_state == ESC_STATE_ALIGN) || (s_state == ESC_STATE_OPENLOOP) ||
     (s_state == ESC_STATE_RUN) || (s_state == ESC_STATE_COAST))
  {
    uint32_t span = (uint32_t)MAX_DUTY_TICKS - MIN_RUN_DUTY_TICKS;

    target = (uint16_t)(MIN_RUN_DUTY_TICKS + ((uint32_t)s_throttle_pm * span) / 1000u);
    if(target < START_DUTY_TICKS)
    {
      target = START_DUTY_TICKS;
    }
    if(target > MAX_DUTY_TICKS)
    {
      target = MAX_DUTY_TICKS;
    }
  }

  /* soft speed governor */
  if((s_state == ESC_STATE_RUN) && (s_interval_ticks < MIN_INTERVAL_TICKS))
  {
    if(s_duty_ticks > (MIN_RUN_DUTY_TICKS + 8u))
    {
      target = s_duty_ticks - 8u;
    }
    else
    {
      target = MIN_RUN_DUTY_TICKS;
    }
  }

  /* duty ramp */
  duty = s_duty_ticks;
  if(duty < target)
  {
    ramp = (uint32_t)ESC_RAMP_UP_TICKS_PER_MS * elapsed_ms;
    duty = ((uint32_t)duty + ramp >= target) ? target : (uint16_t)(duty + ramp);
  }
  else if(duty > target)
  {
    ramp = (uint32_t)ESC_RAMP_DOWN_TICKS_PER_MS * elapsed_ms;
    duty = ((uint32_t)target + ramp >= duty) ? target : (uint16_t)(duty - ramp);
  }

  if(duty != s_duty_ticks)
  {
    s_duty_ticks = duty;
    esc_hw_update_duty(duty);
  }

  /* status / slow measurements */
  s_status.throttle_adc = raw;
  s_status.throttle_pm = s_throttle_pm;
  s_status.duty_pm = (uint16_t)(((uint32_t)s_duty_ticks * 1000u) / ESC_PWM_PERIOD_TICKS);
  s_status.state = s_state;
  s_status.armed = s_armed;
  s_status.step_interval_us = (uint16_t)(s_interval_ticks * ESC_TICK_US);
  if(s_interval_ticks > 0u)
  {
    uint32_t erpm = 60000000u / (6u * s_interval_ticks * ESC_TICK_US);
    s_status.erpm = (erpm > 0xFFFFu) ? 0xFFFFu : (uint16_t)erpm;
  }
  else
  {
    s_status.erpm = 0;
  }

  s_slow_div += elapsed_ms;
  if(s_slow_div >= 20u)
  {
    uint16_t raw_vbus = 0;

    s_slow_div = 0;

#if (ESC_VBAT_DIVIDER_X10 > 0u)
    raw_vbus = esc_hw_read_vbus_raw();
    s_status.vbus_mv = (uint16_t)(((uint32_t)raw_vbus * 3300u * ESC_VBAT_DIVIDER_X10) / (4095u * 10u));
#else
    s_status.vbus_mv = 0;
#endif

#if (ESC_CURRENT_MA_PER_COUNT > 0u)
    {
      uint16_t raw_current = esc_hw_read_current_raw();

      if(raw_current > ESC_CURRENT_ADC_OFFSET)
      {
        uint32_t ma = (uint32_t)(raw_current - ESC_CURRENT_ADC_OFFSET) * ESC_CURRENT_MA_PER_COUNT;
        s_status.current_ma = (ma > 0xFFFFu) ? 0xFFFFu : (uint16_t)ma;
      }
      else
      {
        s_status.current_ma = 0;
      }
    }
#else
    s_status.current_ma = 0;
#endif

#if (ESC_VBAT_MIN_MV > 0u)
    if((s_state != ESC_STATE_IDLE) && (s_state != ESC_STATE_FAULT) &&
       (s_status.vbus_mv > 0u) && (s_status.vbus_mv < ESC_VBAT_MIN_MV))
    {
      primask = __get_PRIMASK();
      __disable_irq();
      esc_stop();
      __set_PRIMASK(primask);
    }
#endif

#if (ESC_CURRENT_LIMIT_MA > 0u)
    if((s_state == ESC_STATE_RUN) && (s_status.current_ma > ESC_CURRENT_LIMIT_MA))
    {
      primask = __get_PRIMASK();
      __disable_irq();
      s_duty_ticks = (s_duty_ticks > 30u) ? (uint16_t)(s_duty_ticks - 30u) : 0u;
      esc_hw_update_duty(s_duty_ticks);
      __set_PRIMASK(primask);
    }
#endif
  }
}

void esc_poll(void)
{
  uint32_t now = s_ms;
  uint32_t elapsed;

  if(now == s_last_ms)
  {
    return;
  }

  elapsed = now - s_last_ms;
  s_last_ms = now;

  if(elapsed > 100u)
  {
    elapsed = 100u;
  }

  esc_slow_update(elapsed);
}

const esc_status_t *esc_status_get(void)
{
  return &s_status;
}

/* ------------------------------------------------------------------------- */
/* init                                                                      */
/* ------------------------------------------------------------------------- */
void esc_init(void)
{
  s_state = ESC_STATE_IDLE;
  s_step = 1;
  s_duty_ticks = 0;
  s_interval_ticks = US_TO_TICKS(ESC_OL_START_INTERVAL_US);
  s_blank_ticks = esc_blank_ticks_for(s_interval_ticks);
  s_last_ms = 0;
  s_zc_pol_flip = (ESC_ZC_INVERT != 0) ? 1u : 0u;

  esc_hw_init();
  esc_hw_all_off();
}
